import json
draft = json.loads('{"objective":"purchase","daily_budget":300000,'
                   '"sets":[{"name":"20대 여성","budget_share":0.6},{"name":"30대","budget_share":0.5}]}')
ALLOWED = {"purchase", "traffic", "awareness", "lead"}
def check(d, min_budget=10000):
    errs = []
    if d["objective"] not in ALLOWED: errs.append("목표 값이 목록에 없음")
    if d["daily_budget"] < min_budget: errs.append("일 예산이 최소값보다 작음")
    s = round(sum(x["budget_share"] for x in d["sets"]), 6)
    if s != 1.0: errs.append(f"세트 예산 비율 합이 {s} (1이어야 함)")
    return errs
print(check(draft))  # ['세트 예산 비율 합이 1.1 (1이어야 함)']
